import subprocess, os, json
from pathlib import Path

repos = set()
for base in ["/home/toxic/estate", "/home/toxic/projects"]:
    if not Path(base).exists():
        continue
    for d in Path(base).rglob(".git"):
        repo = str(d.parent)
        repos.add(repo)
    for f in Path(base).rglob(".git"):
        if f.is_file():
            repo = str(f.parent)
            repos.add(repo)

def run(cmd, cwd):
    try:
        r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=15, cwd=cwd)
        return r.stdout.strip(), r.returncode
    except Exception as e:
        return str(e), 1

processed = 0
merged = 0

for repo in sorted(repos):
    if not (Path(repo) / ".git").exists():
        continue

    # Check if there are merges or dirty state
    status_out, _ = run("git status --short", repo)
    merges_raw, _ = run("git log --merges --format='%H %P %s'", repo)

    if not status_out and not merges_raw:
        # Perfectly clean, single-branch repo
        head, _ = run("git rev-parse HEAD", repo)
        if head:
            run(f"git update-ref refs/recovery/maximal-merge {head}", repo)
        continue

    processed += 1

    # If there are merge commits, merge the top orphaned merge if not merged
    if merges_raw:
        merge_lines = [l for l in merges_raw.split('\n') if l.strip()]
        if merge_lines:
            m_sha = merge_lines[0].split()[0]
            run(f"git merge {m_sha} --no-commit --no-ff", repo)
            conflicts, _ = run("git diff --name-only --diff-filter=U", repo)
            if conflicts:
                for cfile in conflicts.split('\n'):
                    if cfile.strip():
                        run(f"git checkout --theirs '{cfile.strip()}'", repo)
                        run(f"git add '{cfile.strip()}'", repo)

    # Stage remaining untracked/modified (ignoring .gitignore rules)
    run("git add .", repo)

    staged, _ = run("git diff --cached --stat", repo)
    if staged:
        run("git commit -m 'emergent merge: consolidate working copy and resolve merge trees'", repo)
        merged += 1

    head, _ = run("git rev-parse HEAD", repo)
    if head:
        run(f"git update-ref refs/recovery/maximal-merge {head}", repo)
        dec_file = Path(repo) / "MERGE-DECISIONS.md"
        if not dec_file.exists():
            dec_file.write_text(f"# Merge Decisions — {Path(repo).name}\n\nProcessed: true\nResulting commit: {head}\nTag: refs/recovery/maximal-merge\n")

print(f"Processed {processed} repos, executed {merged} active merges with commits.")

